from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def evict_expired(key, t):
        if key in cache:
            value, write_time = cache[key]
            if t >= write_time + ttl:
                del cache[key]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            evict_expired(key, t)
            if key in cache:
                del cache[key]
            else:
                if len(cache) >= capacity:
                    # evict least recently used, but first clean expired ones if needed
                    # find LRU that's not expired first, but per spec expired counts as absent
                    # so we just evict the actual LRU entry (front of OrderedDict)
                    # but should check for expired entries first? spec says expired = absent
                    # so if front is expired, it's already "absent" - but it stays in cache structure
                    # We need to evict considering absence. Let's clean expired entries first.
                    to_remove = []
                    for k, (v, wt) in cache.items():
                        if t >= wt + ttl:
                            to_remove.append(k)
                    for k in to_remove:
                        del cache[k]
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
            cache[key] = (value, t)
        else:
            _, t, key = op
            evict_expired(key, t)
            if key in cache:
                value, write_time = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

